@PostMapping("/api/orders")
public ResponseEntity<?> createOrder(@RequestBody OrderRequest request) {
    try {
        // Validate request
        if (request.getItems() == null || request.getItems().isEmpty()) {
            return ResponseEntity.badRequest().body("Order must have at least one item");
        }

        // Process order
        Order order = new Order();
        order.setCustomerId(request.getCustomerId());
        order.setOrderDate(LocalDateTime.now());
        order.setStatus("PENDING");

        double total = 0;
        for (OrderItem item : request.getItems()) {
            // Calculate price
            double price = item.getQuantity() * item.getUnitPrice();
            total += price;

            // Apply discount if applicable
            if (item.getQuantity() > 10) {
                price *= 0.9; // 10% discount for bulk orders
            }

            order.addItem(item);
        }

        order.setTotal(total);
        orderRepository.save(order);

        // Send confirmation email
        emailService.sendConfirmation(order);

        return ResponseEntity.ok(order);
    } catch (Exception e) {
        logger.error("Error processing order", e);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body("An error occurred while processing your order");
    }
